def is_valid_paren_bracket_sequence(s):
    closing_to_opening = {')': '(', ']': '['}
    stack = []
    for c in s:
        if c in '([':
            stack.append(c)
        elif c in closing_to_opening:
            if not stack or stack.pop() != closing_to_opening[c]:
                return False
        else:
            return False
    return not stack

def count_partitions(n, k):
    if n < 0 or k < 0:
        return 0
    if k == 0:
        return 1 if n == 0 else 0
    if k > n:
        return 0
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def parts(total, parts_count, min_val):
        if parts_count == 0:
            return 1 if total == 0 else 0
        if total < parts_count * min_val:
            return 0
        result = 0
        for first in range(min_val, total // parts_count + 1):
            result += parts(total - first, parts_count - 1, first)
        return result
    return parts(n, k, 1)

