def smart_truncate(s, maxlen):
    if len(s) <= maxlen:
        return s
    limit = maxlen - 3
    if limit <= 0:
        return s[:maxlen]
    cut = s[:limit]
    space_idx = cut.rfind(' ')
    if space_idx != -1:
        cut = cut[:space_idx]
    return cut + '...'

