def remove_first_and_last_occurrence(s, ch):
    first = s.find(ch)
    if first == -1:
        return s
    last = s.rfind(ch)
    chars = list(s)
    if first == last:
        del chars[first]
    else:
        del chars[last]
        del chars[first]
    return ''.join(chars)

